/** Native Survival cassette clicks, saved coverage, topology changes and exactly-once ejection. */
final class NavigationModuleLiveChecks {
    private static final BlockPos ROOT=new BlockPos(182,110,182),SOURCE=ROOT.west(5),PRESS=ROOT.north(8);
    private static int stage,ticks,checks;private static BlockPos bay;private static Vec3d feet;private static boolean sent;private static ItemStack recorded;
    private static void need(boolean ok,String why){checks++;if(!ok)throw new IllegalStateException("Navigation module stage="+stage+" tick="+ticks+": "+why);}
    private static TileEntityNavigationTable table(net.minecraft.world.World w,BlockPos at){return (TileEntityNavigationTable)w.getTileEntity(at);}
    private static EntityPlayerMP player(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayers().get(0);}
    private static void server(Minecraft mc,Runnable task)throws Exception{mc.getIntegratedServer().callFromMainThread(()->{task.run();return null;}).get();}
    private static void aim(EntityPlayerMP p,TileEntityNavigationTable t){MachineMountSurface m=NavigationModuleSlot.surface(t);Vec3d eye=m.center.add(m.normal.scale(2.5)).addVector(0,.3,0),d=m.center.subtract(eye);feet=eye.addVector(0,-p.getEyeHeight(),0);p.connection.setPlayerLocation(feet.x,feet.y,feet.z,(float)Math.toDegrees(Math.atan2(-d.x,d.z)),(float)-Math.toDegrees(Math.atan2(d.y,Math.hypot(d.x,d.z))));p.motionX=p.motionY=p.motionZ=0;}
    private static void mode(EntityPlayerMP p){p.setGameType(GameType.SURVIVAL);p.inventory.currentItem=0;p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.connection.sendPacket(new net.minecraft.network.play.server.SPacketHeldItemChange(0));p.inventoryContainer.detectAndSendChanges();}
    private static void source(WorldServer w){FrameMachineDesign spec=FrameMachineDesign.get("standalone_dish");BridgeMachineChecks.frame(w,SOURCE,spec,0);BridgeMachineChecks.frame(w,SOURCE,spec,2);TileEntityConstructor dish=(TileEntityConstructor)w.getTileEntity(SOURCE);need(dish.assemble(),"formed scanner");TransmitterSlots.configure(dish,ChannelList.of(73),256,false);DeferredTileLoad.flush(w);NavigationWorldChecks.power(w,dish);}
    static boolean tick(Minecraft mc,File output)throws Exception{
        need(++ticks<700,"bounded actual interaction mode="+mc.playerController.getCurrentGameType()+" slot="+mc.player.inventory.currentItem+" held="+mc.player.getHeldItemMainhand()+" position="+mc.player.getPositionVector());mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.hideGUI=true;
        if(stage==0){mc.player.closeScreen();mc.playerController.setGameType(GameType.SURVIVAL);server(mc,()->{EntityPlayerMP p=player(mc);WorldServer w=p.getServerWorld();for(BlockPos at:BlockPos.getAllInBox(ROOT.add(-7,-3,-3),ROOT.add(5,6,4)))w.setBlockToAir(at);p.inventory.clear();Block block=Block.getBlockFromName("vandorlabs:navigation_table_flat");w.setBlockState(ROOT,block.getDefaultState(),2);w.setBlockState(ROOT.east(),block.getDefaultState(),2);NavigationAssemblies.rebuild(w,ROOT);TileEntityNavigationTable a=table(w,ROOT),b=table(w,ROOT.east());need(a.hasMount()!=b.hasMount()&&a.hasModuleBay()!=b.hasModuleBay(),"one chip and one module bay");TileEntityNavigationTable host=a.hasModuleBay()?a:b;bay=host.getPos();need(!host.hasMount(),"bay is on second member");source(w);host.reader().configureDisplay(new NavigationScreenSettings(NavigationMap.SURFACE,true,1,false,false),true,127,0,ChannelList.of(73));for(BlockPos at:BlockPos.getAllInBox(PRESS.add(-1,-1,-1),PRESS.add(5,4,4)))w.setBlockToAir(at);FrameMachineDesign pressSpec=FrameMachineDesign.get("assembly_press");BridgeMachineChecks.frame(w,PRESS,pressSpec,0);BridgeMachineChecks.frame(w,PRESS,pressSpec,2);TileEntityConstructor press=(TileEntityConstructor)w.getTileEntity(PRESS);need(press.assemble(),"manufacturing Press forms");press.setInventorySlotContents(0,com.vandorlabs.programmer.CatalogChipData.masterStack());ItemStack battery=new ItemStack(com.vandorlabs.items.ModItems.BATTERY_MODULE);com.vandorlabs.rack.ModuleBatteryData.receive(battery,10000,false);press.synthesisInventory().setStackInSlot(2,battery);press.synthesisInventory().setStackInSlot(0,new ItemStack(com.vandorlabs.items.ModItems.PROGRAMMABLE_MATTER_INGOT));press.selectDesign(press.builderRecipeIndex("navigation_data_module"));DeferredTileLoad.flush(w);p.setHeldItem(EnumHand.MAIN_HAND,ItemStack.EMPTY);mode(p);aim(p,host);});stage=9;ticks=0;return false;}
        if(stage==9){boolean ready=mc.getIntegratedServer().callFromMainThread(()->{EntityPlayerMP p=player(mc);TileEntityConstructor press=(TileEntityConstructor)p.world.getTileEntity(PRESS);ItemStack result=press.synthesisInventory().getStackInSlot(1);if(result.isEmpty())return false;need(result.getItem()==com.vandorlabs.items.ModItems.NAVIGATION_DATA_MODULE,"actual powered Press manufactures new module");need(press.synthesisInventory().getStackInSlot(0).isEmpty(),"manufacture consumes Matter Ingot");p.setHeldItem(EnumHand.MAIN_HAND,press.synthesisInventory().extractItem(1,1,false));p.inventoryContainer.detectAndSendChanges();return true;}).get();if(!ready)return false;stage=1;ticks=0;return false;}
        if(stage==1||stage==4||stage==6){
            boolean empty=stage==4;if(ticks<15||mc.playerController.getCurrentGameType()!=GameType.SURVIVAL||mc.player.inventory.currentItem!=0||mc.player.getDistanceSq(feet.x,feet.y,feet.z)>.03||mc.player.getHeldItemMainhand().isEmpty()!=empty)return false;
            if(!empty&&(mc.player.getHeldItemMainhand().getItem()!=com.vandorlabs.items.ModItems.NAVIGATION_DATA_MODULE||mc.player.getHeldItemMainhand().getCount()!=1))return false;TileEntityNavigationTable host=table(mc.world,bay);if(host==null||!host.hasModuleBay())return false;MachineMountSurface m=NavigationModuleSlot.surface(host);need(m!=null,"actual low bay surface");mc.playerController.processRightClickBlock(mc.player,mc.world,bay,host.moduleFacing(),m.center,EnumHand.MAIN_HAND);stage++;ticks=0;return false;
        }
        if(stage==2){if(ticks<20)return false;server(mc,()->{EntityPlayerMP p=player(mc);TileEntityNavigationTable host=table(p.world,bay),storage=host.moduleStorage();ItemStack module=storage.storedModule();need(module.getCount()==1&&p.getHeldItemMainhand().isEmpty(),"Survival insertion owns one module and consumes one");need(NavigationModuleData.bound(module)&&NavigationModuleData.dimension(module)==0&&NavigationModuleData.count(module)==1,"first source scan binds dimension");int radius=NavigationSources.radius((TileEntityConstructor)p.world.getTileEntity(SOURCE));need(NavigationSources.contains(NavigationModuleData.areas(module,0),SOURCE.getX()+radius,SOURCE.getZ()),"record entire source radius, beyond viewport");need(!NavigationSources.contains(NavigationModuleData.areas(module,0),SOURCE.getX()+radius+1,SOURCE.getZ()),"no extra coverage");recorded=module.copy();carried(p.getServerWorld());NBTTagCompound saved=storage.writeToNBT(new NBTTagCompound());TileEntityNavigationTable reload=new TileEntityNavigationTable();reload.readFromNBT(saved);need(ItemStack.areItemStacksEqual(module,reload.storedModule()),"module data round trips exactly");need(NavigationModuleData.areas(module,1).isEmpty()&&!NavigationModuleData.record(module,1,java.util.Collections.singletonList(new NavigationSources.Area(0,0,500))),"dimension binding cannot be changed");
            need(!NavigationModuleData.record(module,0,NavigationModuleData.areas(module,0))&&ItemStack.areItemStacksEqual(recorded,module),"repeated scans do not grow saved payload");
            ItemStack enlarged=new ItemStack(com.vandorlabs.items.ModItems.NAVIGATION_DATA_MODULE);need(NavigationModuleData.record(enlarged,0,java.util.Collections.singletonList(new NavigationSources.Area(-31,47,10000))),"record enlarged observer circle");ItemStack enlargedReload=new ItemStack(enlarged.writeToNBT(new NBTTagCompound()));need(NavigationSources.contains(NavigationModuleData.areas(enlargedReload,0),9969,47)&&!NavigationSources.contains(NavigationModuleData.areas(enlargedReload,0),9970,47),"10000 radius persists with exact edge");
            ItemStack maximum=new ItemStack(com.vandorlabs.items.ModItems.NAVIGATION_DATA_MODULE);java.util.List<NavigationSources.Area> areas=new java.util.ArrayList<>();for(int i=0;i<NavigationModuleData.MAX_AREAS;i++)areas.add(new NavigationSources.Area(i*10000,10000,500));need(NavigationModuleData.record(maximum,0,areas)&&NavigationModuleData.count(maximum)==NavigationModuleData.MAX_AREAS,"bounded area capacity");need(!NavigationModuleData.record(maximum,0,java.util.Collections.singletonList(new NavigationSources.Area(-10000,-10000,500))),"full module keeps existing data");
            NBTTagCompound full=maximum.writeToNBT(new NBTTagCompound()),summary=NavigationModuleData.summary(maximum).writeToNBT(new NBTTagCompound());int fullBytes=bytes(full),summaryBytes=bytes(summary);need(fullBytes>12000&&summaryBytes<512,"world updates omit coverage arrays");System.out.println("[vandorlabs] navigation-module-wire PASS full="+fullBytes+" summary="+summaryBytes+" bounded="+NavigationModuleData.MAX_AREAS);
            ((TileEntityConstructor)p.world.getTileEntity(SOURCE)).dismantle();host.reader().setRedstoneChannels(ChannelList.EMPTY);need(!NavigationService.coverage(host.reader()).isEmpty(),"recorded areas survive source disconnect");int chunks=p.getServerWorld().getChunkProvider().getLoadedChunkCount();NavigationService.color(p.world,SOURCE.getX()+radius-1,SOURCE.getZ(),true);need(chunks==p.getServerWorld().getChunkProvider().getLoadedChunkCount(),"offline area reads never load chunks");});stage=3;ticks=0;return false;}
        if(stage==3){if(ticks<20)return false;NavigationModuleVisualChecks.run(mc,output);javax.imageio.ImageIO.write(net.minecraft.util.ScreenShotHelper.createScreenshot(mc.displayWidth,mc.displayHeight,mc.getFramebuffer()),"png",new File(output,"navigation-module-installed.png"));server(mc,()->{EntityPlayerMP p=player(mc);p.inventory.setInventorySlotContents(1,p.getHeldItemMainhand().copy());p.setHeldItem(EnumHand.MAIN_HAND,ItemStack.EMPTY);p.inventoryContainer.detectAndSendChanges();aim(p,table(p.world,bay));});stage=4;ticks=0;return false;}
        if(stage==5){if(ticks<20)return false;server(mc,()->{EntityPlayerMP p=player(mc);need(table(p.world,bay).moduleStack().isEmpty()&&ItemStack.areItemStacksEqual(recorded,p.getHeldItemMainhand()),"actual empty-hand removal preserves all data");aim(p,table(p.world,bay));});stage=6;ticks=0;return false;}
        if(stage==7){if(ticks<25)return false;server(mc,()->{EntityPlayerMP p=player(mc);WorldServer w=p.getServerWorld();TileEntityNavigationTable original=table(w,bay).moduleStorage();BlockPos originalOwner=original.getPos();need(ItemStack.areItemStacksEqual(recorded,original.storedModule()),"reinsertion retains data");w.setBlockState(ROOT.east(2),Block.getBlockFromName("vandorlabs:navigation_table_flat").getDefaultState(),2);NavigationAssemblies.rebuild(w,ROOT);int slots=0,items=0;for(int i=0;i<3;i++){TileEntityNavigationTable t=table(w,ROOT.east(i));if(t.hasModuleBay())slots++;if(!t.storedModule().isEmpty())items++;}need(slots==1&&items==1&&ItemStack.areItemStacksEqual(table(w,originalOwner).storedModule(),recorded),"expansion changes roles without moving or duplicating item ownership");for(int i=0;i<3;i++)if(!ROOT.east(i).equals(originalOwner))w.setBlockToAir(ROOT.east(i));for(int i=0;i<3;i++)NavigationAssemblies.rebuild(w,originalOwner);need(table(w,originalOwner).storedModule().isEmpty()&&!table(w,originalOwner).hasModuleBay(),"singleton loses bay and ejects inventory");int drops=0;for(net.minecraft.entity.item.EntityItem e:w.getEntitiesWithinAABB(net.minecraft.entity.item.EntityItem.class,new AxisAlignedBB(ROOT.add(-3,-3,-3),ROOT.add(6,4,4))))if(NavigationModuleData.item(e.getItem())){drops+=e.getItem().getCount();need(ItemStack.areItemStacksEqual(recorded,e.getItem()),"ejected item retains recorded areas");}need(drops==1,"exactly one module ejected after repeated rebuilds");});System.out.println("[vandorlabs] navigation-module PASS checks="+checks+" Survival insert/remove/reinsert whole-source areas dimension lock saved data offline read bounded payload topology roles single ejection");stage=8;return true;}
        return stage==8;
    }
    private static void carried(WorldServer world){
        java.util.List<com.vandorlabs.vehicle.VehicleStructure.Cell> cells=new java.util.ArrayList<>();for(int i=0;i<2;i++){BlockPos at=ROOT.east(i),local=new BlockPos(i,0,0);NBTTagCompound tag=table(world,at).writeToNBT(new NBTTagCompound());tag.setInteger("x",i);tag.setInteger("y",0);tag.setInteger("z",0);cells.add(new com.vandorlabs.vehicle.VehicleStructure.Cell(local,world.getBlockState(at),tag));}
        com.vandorlabs.vehicle.VehicleStructure original=com.vandorlabs.vehicle.VehicleStructure.display(cells);com.vandorlabs.vehicle.VehicleWorld view=new com.vandorlabs.vehicle.VehicleWorld(world,original);
        for(int turns=0;turns<4;turns++){com.vandorlabs.vehicle.VehicleStructure rotated=com.vandorlabs.vehicle.VehicleRotation.rotate(original,view,turns);com.vandorlabs.vehicle.VehicleWorld carried=new com.vandorlabs.vehicle.VehicleWorld(world,rotated);int count=0;for(net.minecraft.tileentity.TileEntity raw:carried.tiles.values()){TileEntityNavigationTable t=(TileEntityNavigationTable)raw;if(!t.storedModule().isEmpty())count++;need(ItemStack.areItemStacksEqual(recorded,t.moduleStack()),"rotated relative module storage resolves original data");if(t.hasModuleBay())need(t.moduleFacing()==carried.getBlockState(t.getPos()).getValue(BlockVandorDirectional.FACING),"bay facing rotates with housing");}need(count==1,"one module owner in rotated saved snapshot");}
        NBTTagCompound legacy=table(world,ROOT).writeToNBT(new NBTTagCompound());for(String key:new String[]{"NavigationDataModule","NavigationModuleSequence","NavigationModuleStorage","NavigationModuleBay","NavigationModuleFacing"})legacy.removeTag(key);TileEntityNavigationTable old=new TileEntityNavigationTable();old.readFromNBT(legacy);NBTTagCompound round=old.writeToNBT(new NBTTagCompound());need(!round.hasKey("NavigationModuleStorage")&&!round.hasKey("NavigationModuleBay"),"pre-module saved tiles do not gain default ownership fields during snapshot decoding");
    }
    private static int bytes(NBTTagCompound tag){try{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();net.minecraft.nbt.CompressedStreamTools.write(tag,new java.io.DataOutputStream(out));return out.size();}catch(java.io.IOException e){throw new IllegalStateException(e);}}
}
